/* Standard edition: searchable roster, personal pool and efficient selection. */
(()=>{'use strict';
const normalize=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
const compact=s=>normalize(s).replace(/\s/g,'');
function score(c,query){const q=normalize(query),qc=compact(query);if(!q)return 1;if(q==='ad'||q==='ap')return c.buildFamilies.includes(q.toUpperCase())?30:0;const names=[c.name,c.id,...(c.aliases||[])].map(normalize);if(names.some(n=>compact(n)===qc))return 100;if(names.some(n=>compact(n).startsWith(qc)))return 80;if(names.some(n=>compact(n).includes(qc)))return 60;const hay=normalize([c.name,c.id,...(c.aliases||[]),c.role,c.style,c.build,c.damage,...c.classes,...c.roles,...c.roles.map(r=>({Superior:'top',Centro:'mid middle',Tirador:'adc bot',Soporte:'support sup',Jungla:'jungle jungler jg'})[r]||'')].join(' '));const words=hay.split(' ');return q.split(' ').every(t=>words.some(w=>w===t||(t.length>=3&&w.startsWith(t))))?20:0;}
function distance(a,b){a=compact(a);b=compact(b);let row=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){const next=[i];for(let j=1;j<=b.length;j++)next[j]=Math.min(next[j-1]+1,row[j]+1,row[j-1]+(a[i-1]===b[j-1]?0:1));row=next;}return row[b.length];}
function create(A){
 const {D,saved,esc,icon,persist,render,toast,navigate}=A;
 const fresh=()=>({query:'',position:'Todos',build:'Todos',damage:'Todos',kind:'Todos',group:'Todos',letter:'',sort:'name',limit:24,advanced:false,selecting:false,selected:new Set()});
 const states={explore:fresh(),pool:fresh()};let active='explore';
 const current=()=>states[active];
 const membership=id=>saved.pool.includes(id);
 const baseList=scope=>D.champions.filter(c=>scope!=='pool'||membership(c.id));
 const filtered=(scope=active)=>{const s=states[scope];return baseList(scope).map(c=>({c,rank:score(c,s.query)})).filter(({c,rank})=>rank&&(s.position==='Todos'||c.roles.includes(s.position))&&(s.build==='Todos'||c.buildFamilies.includes(s.build))&&(s.damage==='Todos'||c.damageFamily===s.damage)&&(s.kind==='Todos'||c.classes.includes(s.kind))&&(s.group==='Todos'||s.group==='Favoritos'&&saved.favorites.includes(c.id)||s.group==='Sin estudiar'&&!saved.studied.includes(c.id))&&(!s.letter||normalize(c.name).startsWith(s.letter.toLowerCase()))).sort((a,b)=>(s.query?b.rank-a.rank:0)||(s.sort==='recent'?(saved.recents.indexOf(a.c.id)<0?999:saved.recents.indexOf(a.c.id))-(saved.recents.indexOf(b.c.id)<0?999:saved.recents.indexOf(b.c.id)):0)||a.c.name.localeCompare(b.c.name,'es')).map(x=>x.c);};
 function reset(scope=active,keepQuery=false){const old=states[scope];states[scope]={...fresh(),query:keepQuery?old.query:'',selecting:old.selecting,selected:old.selected};}
 function card(c){const s=current(),selection=s.selecting&&['explore','pool'].includes(A.getTab());const selected=s.selected.has(c.id);const inPool=membership(c.id);const buildClass=c.buildFamilies.includes('Tanque')?'hybrid':c.buildFamilies.includes('Híbrido')?'hybrid':c.buildFamilies.includes('AP')?'ap':'ad';return`<article class="roster-card ${selected?'is-selected':''} ${inPool?'is-member':''}"><button class="roster-open" data-action="roster-open" data-id="${c.id}" aria-label="${selection?'Seleccionar':'Consultar'} ${esc(c.name)}" ${selection?`aria-pressed="${selected}"`:''}><div class="roster-portrait"><img src="assets/${saved.rosterView==='gallery'?'champions/'+c.id+'.jpg':'portraits/'+c.id+'.png'}" alt="" loading="lazy" width="64" height="64">${selection?`<span class="selection-check ${selected?'checked':''}">${selected?icon('check'):''}</span>`:''}</div><div class="roster-copy"><h3>${esc(c.name)}</h3><p>${esc(c.roles.join(' · '))}</p><div class="tags"><span class="tag ${buildClass}">${esc(c.build)}</span><span class="tag muted">${esc(c.classes[0]||c.role)}</span>${saved.studied.includes(c.id)?'<span class="tag studied-tag">✓ Estudiado</span>':''}</div></div></button>${!selection?`<button class="roster-member ${inPool?'on':''}" data-action="roster-toggle" data-id="${c.id}" aria-label="${inPool?'Quitar de':'Añadir a'} mi pool: ${esc(c.name)}" aria-pressed="${inPool}">${icon(inPool?'check':'plus')}</button>`:''}</article>`;}
 function activeCount(s){return['build','damage','kind'].filter(k=>s[k]!=='Todos').length;}
 function field(key,label,options,s){return`<label class="filter-field">${label}<select data-roster-select="${key}">${options.map(v=>`<option value="${v}" ${s[key]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;}
 function recentHtml(){const recent=saved.recents.slice(0,6).map(id=>D.champions.find(c=>c.id===id)).filter(Boolean);return recent.length?`<div class="recent-row"><span>RECIENTES</span>${recent.map(c=>`<button data-action="champion" data-id="${c.id}"><img src="assets/portraits/${c.id}.png" alt="" width="24" height="24">${esc(c.name)}</button>`).join('')}</div>`:'';}
 function page(scope){active=scope;const s=current(),isPool=scope==='pool';return`<div class="fade-in standard-page"><div class="page-heading catalog-heading"><div><div class="eyebrow">MAVERICK · STANDARD EDITION</div><h1>${isPool?'Tu selección. Tu estudio.':'Encuentra tu próximo campeón.'}</h1><p>${isPool?'Un espacio propio dentro de toda la Grieta.':'Busca, compara perfiles y construye un pool a tu medida.'}</p></div><div class="catalog-counter"><b>${isPool?saved.pool.length:D.champions.length}</b><span>${isPool?'EN MI POOL':'CAMPEONES'}</span></div></div>${isPool&&!saved.pool.length?`<div class="pool-welcome">${icon('pool')}<div><h2>Empieza por los que te interesan.</h2><p>Explora el catálogo y toca + para añadir un campeón. También puedes seleccionar varios de una vez.</p><button class="primary" data-action="navigate" data-tab="explore">Explorar campeones ${icon('arrow')}</button></div></div>`:''}<section class="catalog-controls" aria-label="Buscar y filtrar campeones"><div class="catalog-search-row"><div class="search-wrap">${icon('search')}<input class="search-input catalog-search" data-search="roster" type="search" autocomplete="off" spellcheck="false" value="${esc(s.query)}" aria-label="Buscar entre ${isPool?'mi pool':'todos los campeones'}" placeholder="Nombre, apodo o estilo… Ej.: Ekko, Kha Zix, mago"><button class="clear-search" data-action="roster-clear-query" aria-label="Borrar búsqueda" ${s.query?'':'hidden'}>${icon('close')}</button></div><button class="filter-toggle ${s.advanced?'active':''}" data-action="roster-advanced" aria-expanded="${s.advanced}">${icon('items')} Filtros${activeCount(s)?` <b>${activeCount(s)}</b>`:''}</button></div><div class="position-chips" aria-label="Posición orientativa">${['Todos','Superior','Jungla','Centro','Tirador','Soporte'].map(p=>`<button class="chip ${s.position===p?'active':''}" data-action="roster-position" data-position="${p}" aria-pressed="${s.position===p}">${p}</button>`).join('')}</div>${s.advanced?`<div class="advanced-filters">${field('build','Compra principal',['Todos','AD','AP','Híbrido','Tanque','Utilidad'],s)}${field('kind','Clase',['Todos','Luchador','Tanque','Mago','Asesino','Tirador','Soporte'],s)}${field('damage','Tipo de daño',['Todos','Físico','Mágico','Mixto'],s)}<p>Posiciones y compras son orientación editorial. AD/AP, daño y clase son conceptos distintos.</p></div>`:''}</section><div id="roster-recents">${!s.query?recentHtml():''}</div><div class="roster-tools"><div class="chips">${['Todos','Favoritos','Sin estudiar'].map(g=>`<button class="chip ${s.group===g?'active':''}" data-action="roster-group" data-group="${g}">${g}</button>`).join('')}</div><div class="roster-tool-actions"><button class="text-button ${s.selecting?'gold':''}" data-action="roster-selection">${icon('check')} ${s.selecting?'Terminar':'Seleccionar'}</button><div class="view-switch" aria-label="Vista de campeones"><button data-action="roster-view" data-view="compact" class="${saved.rosterView!=='gallery'?'active':''}" aria-label="Vista compacta" aria-pressed="${saved.rosterView!=='gallery'}">${icon('study')}</button><button data-action="roster-view" data-view="gallery" class="${saved.rosterView==='gallery'?'active':''}" aria-label="Vista de galería" aria-pressed="${saved.rosterView==='gallery'}">${icon('pool')}</button></div></div></div><div class="alphabet" aria-label="Filtrar por inicial"><button data-action="roster-letter" data-letter="" class="${!s.letter?'active':''}" aria-pressed="${!s.letter}">A–Z</button>${'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('').map(l=>{const exists=baseList(scope).some(c=>normalize(c.name).startsWith(l.toLowerCase()));return`<button data-action="roster-letter" data-letter="${l}" class="${s.letter===l?'active':''}" aria-pressed="${s.letter===l}" ${exists?'':'disabled'}>${l}</button>`;}).join('')}</div><div id="roster-live" aria-live="polite">${resultsHtml()}</div><div id="selection-dock">${dock()}</div></div>`;}
 function empty(){const s=current();const available=baseList(active).filter(c=>score(c,s.query));const nearest=s.query.length>=3?D.champions.map(c=>({c,d:Math.min(distance(s.query,c.name),distance(s.query,c.id),...(c.aliases||[]).map(a=>distance(s.query,a)))})).filter(x=>x.d<=Math.max(1,Math.min(3,Math.floor(compact(s.query).length/3)))).sort((a,b)=>a.d-b.d).slice(0,3):[];return`<div class="empty roster-empty">${icon('search')}<b>${active==='pool'&&!saved.pool.length?'Tu pool está listo para llenarse.':'No hay coincidencias con estos filtros.'}</b>${available.length?`Hay ${available.length} coincidencias fuera de los filtros actuales.`:'Prueba otro nombre, alias o posición.'}<div class="empty-actions"><button class="secondary" data-action="roster-reset">Limpiar filtros</button>${active==='pool'?'<button class="secondary" data-action="navigate" data-tab="explore">Ver todo el catálogo</button>':''}</div>${nearest.length?`<p>Quizás buscabas:</p><div class="suggestions">${nearest.map(({c})=>`<button data-action="roster-suggest" data-name="${esc(c.name)}">${esc(c.name)} ${icon('arrow')}</button>`).join('')}</div>`:''}</div>`;}
 function filterSummary(){const s=current(),filters=[['position','Posición'],['build','Compra'],['kind','Clase'],['damage','Daño'],['group','Grupo'],['letter','Inicial']].filter(([key])=>key==='letter'?!!s[key]:s[key]!=='Todos');return filters.length?`<div class="active-filters">${filters.map(([key,label])=>`<button data-action="roster-unset" data-key="${key}" aria-label="Quitar filtro ${label}: ${esc(s[key])}">${label}: ${esc(s[key])} ${icon('close')}</button>`).join('')}<button class="reset-filters" data-action="roster-reset">Restablecer</button></div>`:'';}
 function resultsHtml(){const s=current(),list=filtered(),shown=list.slice(0,s.limit);return`${filterSummary()}<div class="results-line catalog-results"><span><b>${list.length}</b> ${list.length===1?'campeón':'campeones'}${s.query?` para «${esc(s.query)}»`:''}${s.letter?` · ${s.letter}`:''}</span><label>Orden <select class="roster-sort" data-roster-select="sort" aria-label="Orden de campeones"><option value="name" ${s.sort==='name'?'selected':''}>A–Z</option><option value="recent" ${s.sort==='recent'?'selected':''}>Consultados recientemente</option></select></label></div>${s.selecting?'<p class="selection-hint">Toca las tarjetas para seleccionar varios campeones. La selección se conserva al cambiar filtros.</p>':''}<div class="roster-grid ${saved.rosterView==='gallery'?'gallery':''}" id="roster-grid">${shown.length?shown.map(card).join(''):empty()}</div>${list.length>s.limit?`<div class="load-more"><button class="secondary" data-action="roster-more">Ver ${Math.min(24,list.length-s.limit)} más ${icon('plus')}</button><small>Mostrando ${shown.length} de ${list.length}</small></div>`:''}`;}
 function dock(){const s=current();return s.selecting?`<div class="selection-dock"><div><b>${s.selected.size}</b><span> seleccionados</span><button class="text-button" data-action="roster-clear-selected">Limpiar</button></div><button class="primary" data-action="roster-apply" ${!s.selected.size?'disabled':''}>${active==='pool'?'Quitar del pool':'Añadir a mi pool'} ${icon(active==='pool'?'close':'plus')}</button></div>`:'';}
 function refresh(){const recent=document.querySelector('#roster-recents');if(recent)recent.innerHTML=!current().query?recentHtml():'';const el=document.querySelector('#roster-live');if(el)el.innerHTML=resultsHtml();const dockEl=document.querySelector('#selection-dock');if(dockEl)dockEl.innerHTML=dock();const clear=document.querySelector('.clear-search');if(clear)clear.hidden=!current().query;}
 function updatePool(ids,remove=false){const next=new Set(saved.pool);for(const id of ids)remove?next.delete(id):next.add(id);saved.pool=[...next];persist('pool');}
 function toggle(id){const has=membership(id);updatePool([id],has);render();const b=document.querySelector('#detail-dialog [data-action="roster-toggle"]');if(b){b.innerHTML=icon(has?'plus':'check')+(has?' Añadir a mi pool':' En mi pool');b.setAttribute('aria-pressed',String(!has));}toast(has?'Campeón quitado del pool. Sus notas se conservan.':'Campeón añadido a tu pool');}
 function click(action,b){const s=current(),id=b.dataset.id;switch(action){case'roster-open':if(s.selecting&&['explore','pool'].includes(A.getTab())){s.selected.has(id)?s.selected.delete(id):s.selected.add(id);refresh();}else A.openChampion(id);break;case'roster-toggle':toggle(id);break;case'roster-position':s.position=b.dataset.position;s.letter='';s.limit=24;render();break;case'roster-group':s.group=b.dataset.group;s.limit=24;render();break;case'roster-advanced':s.advanced=!s.advanced;render();break;case'roster-view':saved.rosterView=b.dataset.view;persist('rosterView');render();break;case'roster-letter':s.letter=b.dataset.letter;s.limit=24;render();break;case'roster-more':s.limit+=24;refresh();break;case'roster-selection':s.selecting=!s.selecting;if(!s.selecting)s.selected.clear();render();break;case'roster-clear-selected':s.selected.clear();refresh();break;case'roster-apply':{const n=s.selected.size;updatePool([...s.selected],active==='pool');s.selected.clear();s.selecting=false;render();toast(`${n} ${n===1?'campeón actualizado':'campeones actualizados'} en tu pool`);break;}case'roster-clear-query':s.query='';s.limit=24;document.querySelector('[data-search="roster"]').value='';refresh();document.querySelector('[data-search="roster"]').focus();break;case'roster-unset':s[b.dataset.key]=b.dataset.key==='letter'?'':'Todos';s.limit=24;render();break;case'roster-reset':reset(active,true);render();break;case'roster-suggest':reset();current().query=b.dataset.name;render();break;case'roster-champion-items':document.querySelector('#detail-dialog').close();A.openChampionItems(id);break;}}
 function input(value){const s=current();s.query=value;s.letter='';s.limit=24;document.querySelectorAll('.alphabet button').forEach(b=>{const on=b.dataset.letter==='';b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on));});refresh();}
 function change(key,value){current()[key]=value;current().limit=24;render();}
 function recordRecent(id){saved.recents=[id,...saved.recents.filter(x=>x!==id)].slice(0,12);persist('recents');}
 function detail(c){const inPool=membership(c.id);const stats=c.baseStats;return`<div class="standard-detail-tools"><div class="tags">${c.roles.map(r=>`<span class="tag muted">${esc(r)}</span>`).join('')}<span class="tag muted">${esc(c.guideLabel)}</span></div><div class="detail-actions"><button class="secondary" data-action="roster-toggle" data-id="${c.id}" aria-pressed="${inPool}">${icon(inPool?'check':'plus')} ${inPool?'En mi pool':'Añadir a mi pool'}</button><button class="secondary" data-action="favorite" data-id="${c.id}">${icon('star')} Favorito</button><button class="secondary" data-action="roster-champion-items" data-id="${c.id}">${icon('items')} Consultar objetos</button></div>${c.guideKind==='archetype'?'<p class="caption">Las prioridades siguientes son una orientación por arquetipo, no una build específica verificada del parche. Contrástalas con las habilidades de este campeón y tu partida.</p>':''}</div><details class="official-details"><summary>Habilidades y estadísticas oficiales ${icon('plus')}</summary><div class="base-stats"><span>${stats.hp} vida</span><span>${stats.attackdamage} AD</span><span>${stats.attackspeed} vel. ataque</span><span>${stats.armor} armadura</span><span>${stats.spellblock} RM</span><span>${stats.movespeed} movimiento</span></div><p class="caption">Estadísticas base a nivel 1 · Recurso: ${esc(c.resource)}</p><article class="ability"><b>Pasiva · ${esc(c.passive.name)}</b><p>${esc(c.passive.description)}</p></article>${c.abilities.map(a=>`<article class="ability"><b>${a.key} · ${esc(a.name)}</b><p>${esc(a.description)}</p></article>`).join('')}</details>`;}
 return{explorePage:()=>page('explore'),poolPage:()=>page('pool'),card,click,input,change,recordRecent,detail,filtered,states};
}
window.MaverickRoster={create,normalize,score,distance};
})();
